// Decoded lazily: a third of a megabyte of typed arrays that nothing needs
// until the belt is actually switched on.
let cache = null;

export function decodeAsteroids() {
  if (cache) return cache;

  const bin = atob(PACKED);
  const n = ASTEROID_COUNT;

  const DEG = Math.PI / 180;
  // Laid out for the GPU: two vec3 attributes plus a magnitude.
  const elemA = new Float32Array(n * 3);   // a (AU), e, inclination (rad)
  const elemB = new Float32Array(n * 3);   // node, arg. perihelion, mean anomaly (rad)
  const mag = new Float32Array(n);

  const scale = FIELD_ORDER.map((k) => {
    const [lo, hi] = RANGES[k];
    return [lo, (hi - lo) / 65535];
  });
  const u16 = (o) => bin.charCodeAt(o) | (bin.charCodeAt(o + 1) << 8);

  for (let k = 0; k < n; k++) {
    const base = k * 14;
    const v = [];
    for (let f = 0; f < 7; f++) {
      const [lo, s] = scale[f];
      v.push(lo + u16(base + f * 2) * s);
    }
    elemA[k * 3] = v[0];
    elemA[k * 3 + 1] = v[1];
    elemA[k * 3 + 2] = v[2] * DEG;
    elemB[k * 3] = v[3] * DEG;
    elemB[k * 3 + 1] = v[4] * DEG;
    elemB[k * 3 + 2] = v[5] * DEG;
    mag[k] = v[6];
  }

  cache = { count: n, elemA, elemB, mag };
  return cache;
}
